void signal_handler(int sig) {
    // Process woke up due to signal delivery (e.g., SIGALRM, SIGUSR1)
}

struct sigaction sa = {0};
sa.sa_handler = signal_handler;
sigaction(SIGALRM, &sa, NULL);

// Suspends execution until a signal is caught.
// Return value is always -1 if it returns, as EINTR is the standard flow.
int ret = pause();

if (ret == -1 && errno == EINTR) {
    // Expected behavior: signal caught, handler executed.
}

